          <!-- Data Cells -->
          <td 
            v-for="(cell, colIdx) in row" 
            :key="`cell-${rowIdx}-${colIdx}`"
            class="p-2 border min-w-24 cursor-cell text-sm"
            :class="{ 
              'bg-blue-200': isSelected(rowIdx, colIdx),
              'border-blue-400': isSelected(rowIdx, colIdx)
            }"
            @click="selectCell(rowIdx, colIdx, $event)"
            @dblclick="editCell(rowIdx, colIdx)"
          >
            <!-- Display Mode -->
            <div v-if="!isEditing(rowIdx, colIdx)" class="truncate">
              {{ cell }}
            </div>

            <!-- Edit Mode -->
            <input 
              v-else
              v-model="tableData[rowIdx][colIdx]"
              type="text"
              class="input input-sm input-bordered w-full"
              @keydown.enter="saveCell(rowIdx, colIdx)"
              @keydown.escape="cancelEdit"
              @blur="saveCell(rowIdx, colIdx)"
              autofocus
            />
          </td>

          <!-- Row Delete Button -->
          <td class="w-8 p-2 border text-center">
            <button 
              @click="deleteRow(rowIdx)" 
              class="text-gray-400 hover:text-red-500 text-sm"
            >
              <i class="fa-solid fa-times"></i>
            </button>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script>
export default {
  props: {
    initialData: {
      type: Array,
      required: true
    },
    tableId: {
      type: String,
      required: true
    }
  },
  emits: ['update-table'],
  data() {
    return {
      tableData: [],
      selectedRows: new Set(),
      selectedColumns: new Set(),
      selectedCells: new Set(),
      editingCell: null,
      clipboard: null
    }
  },
  computed: {
    headers() {
      if (!this.tableData.length) return []
      return this.tableData[0].map((_, idx) => `Column ${String.fromCharCode(65 + idx)}`)
    },
    hasSelection() {
      return this.selectedRows.size > 0 || this.selectedColumns.size > 0 || this.selectedCells.size > 0
    },
    allRowsSelected() {
      return this.selectedRows.size === this.tableData.length && this.tableData.length > 0
    }
  },
  watch: {
    tableData: {
      handler(newData) {
        this.$emit('update-table', {
          id: this.tableId,
          data: JSON.parse(JSON.stringify(newData))
        })
      },
      deep: true,
      immediate: false
    }
  },
  mounted() {
    this.tableData = JSON.parse(JSON.stringify(this.initialData))
  },
  methods: {
    isSelected(rowIdx, colIdx) {
      const key = `${rowIdx},${colIdx}`
      return this.selectedCells.has(key) || 
             this.selectedRows.has(rowIdx) || 
             this.selectedColumns.has(colIdx)
    },
    isEditing(rowIdx, colIdx) {
      return this.editingCell === `${rowIdx},${colIdx}`
    },
    selectCell(rowIdx, colIdx, event) {
      const key = `${rowIdx},${colIdx}`
      if (event.ctrlKey || event.metaKey) {
        this.selectedCells.has(key) ? this.selectedCells.delete(key) : this.selectedCells.add(key)
      } else if (event.shiftKey) {
        // Range selection would go here
      } else {
        this.selectedCells.clear()
        this.selectedRows.clear()
        this.selectedColumns.clear()
        this.selectedCells.add(key)
      }
    },
    selectRow(rowIdx) {
      this.selectedRows.clear()
      this.selectedColumns.clear()
      this.selectedCells.clear()
      this.selectedRows.add(rowIdx)
    },
    toggleSelectRow(rowIdx) {
      this.selectedRows.has(rowIdx) ? this.selectedRows.delete(rowIdx) : this.selectedRows.add(rowIdx)
      this.selectedColumns.clear()
      this.selectedCells.clear()
    },
    selectColumn(colIdx) {
      this.selectedColumns.clear()
      this.selectedRows.clear()
      this.selectedCells.clear()
      this.selectedColumns.add(colIdx)
    },
    toggleSelectAll() {
      if (this.allRowsSelected) {
        this.selectedRows.clear()
      } else {
        this.selectedRows.clear()
        for (let i = 0; i < this.tableData.length; i++) {
          this.selectedRows.add(i)
        }
      }
      this.selectedColumns.clear()
      this.selectedCells.clear()
    },
    editCell(rowIdx, colIdx) {
      this.editingCell = `${rowIdx},${colIdx}`
    },
    saveCell(rowIdx, colIdx) {
      this.editingCell = null
    },
    cancelEdit() {
      this.editingCell = null
    },
    addRow() {
      const newRow = new Array(this.tableData[0]?.length || 3).fill('')
      this.tableData.push(newRow)
    },
    deleteRow(rowIdx) {
      this.tableData.splice(rowIdx, 1)
      this.selectedRows.delete(rowIdx)
    },
    addColumn() {
      this.tableData.forEach(row => row.push(''))
    },
    deleteColumn() {
      if (this.selectedColumns.size !== 1) return
      const colIdx = Array.from(this.selectedColumns)[0]
      this.tableData.forEach(row => row.splice(colIdx, 1))
      this.selectedColumns.clear()
    },
    deleteSelected() {
      if (this.selectedRows.size > 0) {
        const rowsToDelete = Array.from(this.selectedRows).sort((a, b) => b - a)
        rowsToDelete.forEach(idx => this.tableData.splice(idx, 1))
        this.selectedRows.clear()
      }
    },
    copySelected() {
      if (this.selectedRows.size > 0) {
        this.clipboard = this.selectedRows.size === 1 
          ? [this.tableData[Array.from(this.selectedRows)[0]]]
          : Array.from(this.selectedRows).map(idx => this.tableData[idx])
      }
    }
  }
}
</script>
